mapper.select:
/* MultiWgMapper.selectMultiWgList : Multi 멀티중량 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT * FROM ( SELECT od.OD_JOB_NO
,od.BOUND ,od.BOUND_TYPE ,od.CD_TYPE ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.REGISTER_USER_ID) AS REGISTER_USER_NAME ,od.REGISTER_DATE_TIME ,od.HBL_NO ,od.AR_DATE ,od.DELIVERY_NAME ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = multi.CUSTOMER_CODE) AS ACCOUNT_NAME ,od.CONSIGNEE_NAME_LOC ,od.GWT ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_CODE_LV1_NAME ,od.SHIPPER_NAME ,od.AMOUNT_LOC ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = multi.DELIVERER_USER_ID) AS DELIVERER_USER_NAME ,od.OB_DATE ,multi.DELIVERY_NAME_CHANGED ,multi.PAYMENT_GUBN ,multi.RECIPIENT_NAME ,multi.DELIVERY_DATE ,multi.PIECES ,multi.RECEIPT_DATE ,multi.VWT ,multi.DELIVERY_FEE ,multi.DELIVERY_NO_CHANGED ,od.ENT_BUSINESS_CODE ,CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE ENT_CODE = od.ENT_CODE AND FUNC_JOB_NO = od.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
,od.CUST_CODE_LV1 ,od.CUST_CODE_LV2
FROM TB_ECM_OD od INNER JOIN ( SELECT OD_JOB_NO , MAX(DELIVERY_CODE) AS DELIVERY_NAME_CHANGED , MAX(PAYMENT_GUBN) AS PAYMENT_GUBN , MAX(RECIPIENT_NAME) AS RECIPIENT_NAME , MAX(DELIVERY_DATE) AS DELIVERY_DATE , MAX(RECEIPT_DATE) AS RECEIPT_DATE , MAX(DELIVERY_NO_CHANGED) AS DELIVERY_NO_CHANGED , MAX(CUSTOMER_CODE) AS CUSTOMER_CODE , MAX(DELIVERER_USER_ID) AS DELIVERER_USER_ID , SUM(VWT) AS VWT , SUM(DELIVERY_FEE) AS DELIVERY_FEE , SUM(PIECES) AS PIECES FROM TB_ECM_OD_MULTI GROUP BY OD_JOB_NO )multi ON od.OD_JOB_NO = multi.OD_JOB_NO WHERE od.BL_TYPE_MH = 'H' AND od.ENT_CODE = #{srchEntCode}
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND ${srchCusType} = #{srchCustomerCode}
AND od.HBL_NO IN (#{item})
AND od.HBL_NO LIKE CONCAT('%',#{srchHblNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
) INFO WHERE 1 = 1

mapper.delete:
/* MultiWgMapper.deleteMultiWgSeq : 멀티(중량) Delete */
DELETE FROM TB_ECM_OD_MULTI
WHERE OD_JOB_NO = #{odJobNo}		
AND SEQ_NO_ID = #{seqNoId}

/* MultiWgMapper.deleteMultiWgOrder : 멀티(중량) Delete */
DELETE FROM TB_ECM_OD_MULTI
WHERE OD_JOB_NO = #{odJobNo}

mapper.insert:
/* MultiWgMapper.insertMulti : Order 멀티(중량)화물 insert */
INSERT INTO TB_ECM_OD_MULTI(
	OD_JOB_NO
	,SEQ_NO_ID
	,DELIVERY_NO
	,DELIVERY_CODE
	,CUSTOMER_CODE
	,DELIVERY_NO_CHANGED
	,PAYMENT_GUBN
	,DELIVERY_FEE
	,PIECES
	,DIM_WIDTH
	,DIM_LENGTH
	,DIM_HEIGHT
	,VWT
	,REMARKS
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
)
SELECT
    #{odJobNo}
    ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_MULTI WHERE OD_JOB_NO = #{odJobNo})
	,#{deliveryNo}
	,#{deliveryCode}
	,#{customerCode}
    ,#{deliveryNoChanged}
    ,#{paymentGubn}
    ,#{deliveryFee}
    ,#{pieces}
    ,#{dimWidth}
    ,#{dimLength}
    ,#{dimHeight}
    ,#{vwt}
    ,#{remarks}
    ,#{registerUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())

mapper.update:
/* MultiWgMapper.updateMulti : 멀티(중량)화물 확정 */

UPDATE TB_ECM_OD_MULTI
SET RECIPIENT_NAME = #{recipientName}
,RECEIPT_DATE = CONVERT(DATE, #{receiptDate},  ${dateFormat})
WHERE OD_JOB_NO = #{odJobNo}

	AND SEQ_NO_ID = #{seqNoId}




UPDATE TB_ECM_OD_MULTI
SET RECIPIENT_NAME = NULL
,RECEIPT_DATE = NULL
WHERE OD_JOB_NO = #{odJobNo}

	AND SEQ_NO_ID = #{seqNoId}
